import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易阐真 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易阐真 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"zh/classics/chanzhen/010.md","filePath":"zh/classics/chanzhen/010.md"}'),s={name:"zh/classics/chanzhen/010.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：小畜，柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也；自我西郊，施未行也。</p></blockquote><h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>初九：复自道，何其咎，吉。</p><p>九二：牵复，吉。</p><p>九三:舆说辐，夫妻反目。</p><p>六四：有孚血，去惕出，无咎。</p><p>九五：有孚挛如，富以其邻。</p><p>上九：既雨既处，尚德载妇。贞厉。月几望，君子征凶。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：风行天上，小畜。君子以懿文德。</p><p>小畜者，养之小也。上巽风，下乾天，是风行天上也。风行天上，鼓动万物，所养者广；风行天上，只可清热解燥，所养者少，小畜之象也。</p><p>君子有见于此，知尽性至命之学，乃窃阴阳，夺造化，转生杀，扭枢机之大事，非得心传者不能行。但大畜不能，亦须小畜，以是懿文德焉。懿者，美也，妆饰之谓。文者，威仪云为之文。威仪云为，虽非修德之大事，亦修德者之不可忽。如应物平顺，执事恭敬，动作详细，言语谨慎之类。藏其刚而用其柔，瞻前顾后，从容不迫，自无躁动失德之行，亦如风吹天上，燥气悉化也。修德而至燥气悉化，能小畜而即能大畜矣。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>畜，敕六反。说，音脱。几，音机。</p><p>小畜者，小其养也。卦德上巽伏下乾健，健而巽行，巽伏其健，健不自用，故谓小畜。此以小养大之卦，承上师卦而来。师之道，借阳而退阴也。借阳退阴，贵乎先养其阳，能养其阳，则以小自居，满而不盈，刚而不躁，有若无，实若虚，其心日下，其德日高，可以渐造于圣贤之域，此小畜所以有亨道也。但小畜虽亨，若大过于小，是柔道用事，刚道退位，志气不振，懦弱无能，畜之小而亨之小，其行不远，大道难成，犹如“密云不雨，自我西郊”也。</p><p>阴气结而为云，阳气通而为雨。只云不雨，阴气盛而阳气弱，生机将息，我家之近者，尚无济，他家之远者，更何求?空空一小，入于寂灭之学，岂能还我乾元面目乎?此小畜之火候，不可不知也。</p><p>初九，刚而居卑，韬明养晦，抱道而处，不以外假而伤内真，是能复于自道也。能复自道，虽畜之小而得其养，刚气日增，不但无咎，而且致吉。此大而自小之畜也。</p><p>九二，刚以柔用，敏而好学，不耻下问，结交有道君子，彼此资益，明善复初，是为牵复也。牵复之畜，外愈虚而内愈实，小而反得其吉。此大而知小之畜也。</p><p>九三，刚而自用，有己无人，乖和失中，终必败刚，如舆说辐，而车不能行，又如夫妻反目，而家不能兴。此大而不知小之畜也。</p><p>六四，以无能而处于有能之中，必有血伤之咎。然柔而得正，自信一己纯阴，为害最大，而能借他家之阳，儆惕勉力，炼己持心，本有害者，可以脱去其害，本有咎者，可以归于无咎。此小而知大之畜也。</p><p>九五，阳刚巽进于中正，真信在中，阴阳混合，金丹凝结，是有孚挛如矣。挛如之信，本固邦宁，命基坚牢，急须化其气质之性，以归真知之性，如富以邻矣。此小而藏大之畜也。</p><p>上九，刚居柔位，在小畜之终，如既雨既处矣。雨所以济亢旱，既雨则阳气处而不亢，既处则阳气和而雨无用。修道所以用阴者，特以制暴躁之假阳耳。假阳既息，真阳须进，小畜之终，正当大畜之时。若终于小而不能大，阴反伤阳，如尚德载妇，女子掌权，又如月几于望，光明渐亏。修道君子，只知小而不知大，以之孤寂守静，无作无为则可，以之尽性至命，行道致远，适以招凶而已。此终于小而不知大之畜也。</p><p>观于六爻之言，小畜原有亨道，是在人小之如何耳。小之当，则以小畜大而致吉；小之不当，则以小害大而招凶。学者可不先究其小中之火候乎?</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
